gah1(){return"\u0647\u062c\u0648\u0645\u064a"},
gagW(){return"\u0647\u0646\u0627 \u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u0645\u0628\u0627\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u064a \u0644\u064f\u0639\u0628\u062a \u0648\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u062e\u0635\u0645 \u0627\u0644\u0642\u0627\u062f\u0645. \u0627\u0644\u0645\u0633 \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629 \u0644\u062a\u0631\u0649 \u0627\u0644\u062a\u0642\u064a\u064a\u0645\u0627\u062a \u0648\u0633\u064a\u0631 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0648\u0623\u0628\u0631\u0632 \u0627\u0644\u0644\u062d\u0638\u0627\u062a."},
gagX(){return"\u064a\u0645\u062a\u0644\u0626 \u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u062e\u0635\u0645 \u0628\u0645\u0627 \u064a\u062c\u0645\u0639\u0647 \u0627\u0644\u0643\u0634\u0651\u0627\u0641\u060c \u0648\u0625\u0646 \u0644\u0645 \u062a\u0631\u0633\u0644 \u0643\u0634\u0651\u0627\u0641\u064b\u0627 \u0625\u0644\u0649 \u062e\u0635\u0645 \u0641\u0633\u064a\u0628\u0642\u0649 \u062a\u0642\u0631\u064a\u0631\u0647 \u0646\u0627\u0642\u0635\u064b\u0627. \u062a\u0646\u0628\u064a\u0647\u0627\u062a \u0646\u0642\u0627\u0637 \u0627\u0644\u0636\u0639\u0641 \u0641\u064a \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u062a\u0642\u0648\u062f\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u0625\u0644\u0649 \u0634\u0627\u0634\u062a\u064a \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0648\u0627\u0644\u062e\u0637\u0629."},
gagY(){return"\u062a\u064f\u062d\u0633\u0645 \u0627\u0644\u062a\u0642\u064a\u064a\u0645\u0627\u062a \u0628\u0639\u062f \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629\u060c \u0648\u064a\u064f\u062d\u0633\u0628 \u0645\u0633\u062a\u0648\u0649 \u0644\u0627\u0639\u0628\u0643 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0645\u062a\u0648\u0633\u0637."},
gEV(){return"\u062a\u0639\u0630\u0631 \u062a\u062d\u0645\u064a\u0644 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0645\u0631\u0643\u0632 \u0627\u0644\u0637\u0628\u064a."},
