gUH(){return"\u0627\u0644\u0645\u062c\u0645\u0639 \u0627\u0644\u0635\u062d\u064a \u0627\u0644\u0646\u062e\u0628\u0648\u064a"},
gbgW(){return"\u0645\u062f\u0631\u0628\u0648 \u0627\u0644\u0644\u064a\u0627\u0642\u0629"},
