ga8n(){return"\u062a\u0639\u0630\u0631 \u062a\u062d\u0645\u064a\u0644 \u0627\u0644\u0631\u0639\u0627\u064a\u0627\u062a"},
ga8o(){return"\u0641\u0634\u0644 \u0627\u0644\u062a\u0648\u0642\u064a\u0639 \u2014 \u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627"},
gtQ(){return"\u0627\u0644\u0631\u0639\u0627\u064a\u0627\u062a"},
gXw(){return"\u0627\u0644\u0645\u0624\u062a\u0645\u0631 \u0627\u0644\u0635\u062d\u0641\u064a"},
gb2B(){return"\u0648\u0627\u062b\u0642"},
gb2C(){return"\u0627\u0644\u062e\u0635\u0645 \u0633\u064a\u0633\u0645\u0639 \u0630\u0644\u0643"},
gb2D(){return"\u062f\u0628\u0644\u0648\u0645\u0627\u0633\u064a"},
gb2E(){return"\u0644\u0646 \u064a\u0646\u0632\u0639\u062c \u0623\u062d\u062f"},
